<?php

namespace App\Http\Requests\Api\V1\Classes;

use App\Enums\ClassStatus;
use App\Models\SchoolClass;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Support\Facades\Gate;
use Illuminate\Validation\Rule;

class StoreClassRequest extends FormRequest
{
    /**
     * Authorization runs before validation so non-admins get 403 instead of validation errors.
     */
    public function authorize(): bool
    {
        Gate::authorize('create', SchoolClass::class);

        return true;
    }

    /**
     * `code` is generated by the server (BR-CLS-03), so it is never accepted here.
     *
     * @return array<string, array<int, mixed>>
     */
    public function rules(): array
    {
        return [
            'name' => ['required', 'string', 'max:255'],
            'description' => ['nullable', 'string', 'max:65535'],
            'status' => ['sometimes', 'string', Rule::enum(ClassStatus::class)],
            'start_at' => ['required', 'date_format:Y-m-d'],
            'end_date' => ['required', 'date_format:Y-m-d', 'after_or_equal:start_at'],
        ];
    }
}
